#include <stdio.h>
struct Rec { int id; int score; };
int main(void) {
    struct Rec a[3] = {{1,10},{2,20},{3,30}};
    FILE *w = fopen("r.dat", "wb");
    fwrite(a, sizeof(struct Rec), 3, w);
    fclose(w);
    FILE *u = fopen("r.dat", "r+b");
    struct Rec upd = {2, 99};
    fseek(u, 1L * sizeof(struct Rec), SEEK_SET);   /* 跳到第 2 条 */
    fwrite(&upd, sizeof(struct Rec), 1, u);
    fflush(u);
    fseek(u, 0L, SEEK_SET);
    struct Rec b[3];
    fread(b, sizeof(struct Rec), 3, u);
    fclose(u);
    for (int i = 0; i < 3; i++) printf("id=%d score=%d\n", b[i].id, b[i].score);
    return 0;
}
